(function(){
 // deterministic RNG so generated question ids stay stable
 let seed=20261120; const rnd=()=>{seed=(seed*1103515245+12345)%2147483648;return seed/2147483648;};
 const pick=(arr,n)=>{const a=arr.slice();const out=[];while(out.length<n&&a.length){out.push(a.splice(Math.floor(rnd()*a.length),1)[0]);}return out;};
 const ALL=PRACTICES.general.concat(PRACTICES.ps);
 const list=(a)=>a.join("; ");
 Object.keys(ACTS).forEach(k=>{
  const A=ACTS[k]; const none=ALL.filter(p=>A.E.indexOf(p)<0&&A.S.indexOf(p)<0);
  const full="'"+A.n+"' ENABLING practices ("+A.E.length+"): "+list(A.E)+". SUPPORTING practices ("+A.S.length+"): "+list(A.S)+".";
  pick(A.E,3).forEach(c=>{
   const pool=A.S.concat(none); const d=pick(pool,3);
   QB.push({m:"m6x",l:k,g:1,q:"Which practice is listed as an ENABLING practice for the '"+A.n.toLowerCase()+"' activity?",o:[c].concat(d),e:full,x:d.map(p=>A.S.indexOf(p)>=0?p+" is a SUPPORTING (not enabling) practice for "+A.n.toLowerCase()+".":p+" is not listed for "+A.n.toLowerCase()+".")});
  });
  pick(A.S,2).forEach(c=>{
   const d=pick(A.E,3);
   QB.push({m:"m6x",l:k,g:1,q:"Which practice is listed as a SUPPORTING (not enabling) practice for the '"+A.n.toLowerCase()+"' activity?",o:[c].concat(d),e:full,x:d.map(p=>p+" is an ENABLING practice for "+A.n.toLowerCase()+".")});
  });
  if(none.length>=1){
   const c=pick(none,1)[0]; const d=pick(A.E.concat(A.S),3);
   QB.push({m:"m6x",l:k,g:1,q:"Which practice is NOT listed (neither enabling nor supporting) for the '"+A.n.toLowerCase()+"' activity?",o:[c].concat(d),e:full,x:d.map(p=>p+" is listed as "+(A.E.indexOf(p)>=0?"ENABLING":"SUPPORTING")+" for "+A.n.toLowerCase()+".")});
  }
 });
 const gl="GENERAL management practices (12): "+list(PRACTICES.general)+". PRODUCT AND SERVICE management practices (22): "+list(PRACTICES.ps)+".";
 pick(PRACTICES.general,6).forEach(c=>{const d=pick(PRACTICES.ps,3);QB.push({m:"m6",l:"m6c",g:1,q:"Which of these is a GENERAL management practice?",o:[c].concat(d),e:gl,x:d.map(p=>p+" is a product and service management practice.")});});
 pick(PRACTICES.ps,6).forEach(c=>{const d=pick(PRACTICES.general,3);QB.push({m:"m6",l:"m6c",g:1,q:"Which of these is a PRODUCT AND SERVICE management practice?",o:[c].concat(d),e:gl,x:d.map(p=>p+" is a general management practice.")});});
 // Sort exercises built from the tables (items sampled at play time)
 const gs=SORTS.find(s=>s.t.indexOf("General or product")===0);
 if(gs){gs.items=PRACTICES.general.map(p=>[p,"General (12)"]).concat(PRACTICES.ps.map(p=>[p,"Product and service (22)"]));gs.sample=10;}
 // Source conflict: the Table B.1 slide (practices lesson) marks Service catalogue management as S for transition,
 // while the 'Transition: management practices' slide lists it as enabling. Keep it out of generated items for transition.
 // Runs after generation and uses no random draws, so the ids (question text + correct answer) of generated questions do not change.
 const AMBIG={a5:["Service catalogue management"]};
 for(let i=QB.length-1;i>=0;i--){const q=QB[i]; if(!q.g||!AMBIG[q.l])continue; const bad=AMBIG[q.l], A=ACTS[q.l], nm=A.n.toLowerCase();
  if(bad.indexOf(q.o[0])>=0){QB.splice(i,1);continue;}
  q.o.forEach((opt,j)=>{ if(j===0||bad.indexOf(opt)<0)return;
   let pool,why;
   if(q.q.indexOf("ENABLING practice")>=0){pool=A.S.concat(ALL.filter(p=>A.E.indexOf(p)<0&&A.S.indexOf(p)<0)); why=p=>A.S.indexOf(p)>=0?p+" is a SUPPORTING (not enabling) practice for "+nm+".":p+" is not listed for "+nm+".";}
   else if(q.q.indexOf("SUPPORTING")>=0){pool=A.E; why=p=>p+" is an ENABLING practice for "+nm+".";}
   else return; // 'NOT listed' questions: the practice is listed in both sources, so it stays a valid distractor
   const rep=pool.find(p=>bad.indexOf(p)<0&&q.o.indexOf(p)<0); if(!rep)return;
   q.o[j]=rep; if(q.x)q.x[j-1]=why(rep);
  });
  q.e+=" Note: the Table B.1 slide marks "+bad.join(", ")+" as S (supporting) for "+nm+", while the "+A.n+" slide lists it as enabling, so it is not tested here.";
 }
 Object.keys(ACTS).forEach(k=>{const A=ACTS[k];const bad=AMBIG[k]||[];SORTS.push({m:"m6x",t:A.n+": enabling or supporting?",buckets:["Enabling","Supporting"],sample:8,items:A.E.map(p=>[p,"Enabling"]).concat(A.S.map(p=>[p,"Supporting"])).filter(it=>bad.indexOf(it[0])<0)});});
})();

